<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id'])){http_response_code(403);exit('Inhaber-Anmeldung erforderlich.');}
require_once dirname(__DIR__).'/private/web_update.php';require_once dirname(__DIR__).'/private/ui.php';
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$action=(string)($_POST['action']??'');
 try{
  if($action==='backup'){$m=gszDatabaseBackup($pdo,gszSchemaCurrent($pdo)?'manuell':'vor-update');gszAudit($pdo,(int)$_SESSION['admin_id'],'backup_created',['file'=>$m['file'],'sha256'=>$m['sha256']]);$_SESSION['app_notice']='Sicherung erstellt. Bitte jetzt herunterladen und aufbewahren.';}
  elseif($action==='upgrade'){$r=gszWebUpgrade($pdo,$config,(int)$_SESSION['admin_id'],(string)($_POST['owner_password']??''),$_POST,(string)($_SERVER['REMOTE_ADDR']??''));$_SESSION['app_notice']=$r['status']==='current'?'Update abgeschlossen. Die Zentrale ist auf Stand 420.'.(!empty($r['files_failed'])?' Einige alte Programmdateien konnten nicht gelöscht werden – siehe Systemstatus.':''):'Update-Status prüfen.';}
  elseif($action==='repair'){$r=gszWebRepair380($pdo,(int)$_SESSION['admin_id'],(string)($_POST['owner_password']??''),$_POST,(string)($_SERVER['REMOTE_ADDR']??''));$_SESSION['app_notice']=$r['status']==='current'?'Struktur angeglichen. Die Zentrale ist vollständig aktuell.':($r['status']==='upgrade'?'Struktur angeglichen. Jetzt noch das Update ausführen.':'Angleichung ausgeführt, Status bitte prüfen.');}
  else throw new RuntimeException('Aktion unbekannt.');
 }catch(Throwable $e){$_SESSION['app_error']=str_starts_with($e->getMessage(),'GSZ_')?'Vorgang gestoppt. Es wurde nichts gelöscht. Bitte Systemstatus prüfen.':$e->getMessage();}
 redirect('update.php');}
$inspection=['status'=>'blocked','code'=>'GSZ_SCHEMA_UNKNOWN','version'=>null];try{$inspection=gszSetupInspect($pdo);}catch(Throwable $e){}
$backups=[];try{$backups=gszBackupList(5);}catch(Throwable $e){}
$latest=$backups[0]??null;$fresh=$latest&&strtotime($latest['created_at'])>=time()-7200;
gszPageStart('Sicherung und Update');
if($inspection['status']==='current'):?>
<section class="card"><h2>Alles aktuell</h2><p>Die Zentrale läuft auf dem aktuellen Stand. Es ist kein Update nötig.</p></section><section class="card"><h2>Sicherung</h2><p>Komplette Datenbank sichern und auf Mac oder iPhone herunterladen.</p><form method="post"><?php gszFields('backup');?><button class="primary">Sicherung jetzt erstellen</button></form><?php foreach($backups as $b):?><p><a href="backup_download.php?file=<?=e(rawurlencode($b['file']))?>">Sicherung vom <?=e((new DateTimeImmutable($b['created_at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y, H:i'))?> Uhr herunterladen</a></p><?php endforeach?></section>
<?php elseif($inspection['status']==='upgrade'):?>
<section class="card"><h2>Neue Version bereit</h2><p>Die Programmdateien sind neu, die Datenbank noch auf Stand <?=e((string)$inspection['version'])?>. <?=(int)$inspection['version']>=380?((int)$inspection['version']>=390?'':'Das Update ergänzt die Merkliste (To-dos, Einkaufsliste, „Rechnungen offen“). ').((int)$inspection['version']>=400?'':'Dazu kommt die Ferienwohnung: Airbnb- und Booking-Kalender planen die Reinigungen. ').((int)$inspection['version']>=410?'':'Neu: Bauprojekte – Gewerke, Handwerker, Termine, Kosten, Mängel und Gewährleistung an einem Ort. ').'Dazu: Website-Anfragen in der Zentrale, Notdienst-Status für die Website und Website-Zahlen. Es werden nur neue Tabellen angelegt, alle Daten bleiben unverändert.':'Das Update entfernt den alten Finanzbereich (Rechnungen, Angebote, Buchhaltung, Sparkasse) und ergänzt Mietabgleich und Abfall-Blöcke. Alle anderen Daten bleiben erhalten. Danach kommen die Merkliste und die Ferienwohnung-Kalender dazu.'?></p></section>
<section class="card"><h2>1. Sicherung erstellen</h2><p>Die Sicherung enthält die komplette Datenbank und wird geschützt auf dem Server abgelegt. Lade sie zusätzlich auf deinen Mac oder dein iPhone herunter.</p>
<form method="post"><?php gszFields('backup');?><button class="primary">Sicherung jetzt erstellen</button></form>
<?php foreach($backups as $b):?><p class="row-line"><a href="backup_download.php?file=<?=e(rawurlencode($b['file']))?>">Sicherung vom <?=e((new DateTimeImmutable($b['created_at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y, H:i'))?> Uhr herunterladen</a></p><?php endforeach?></section>
<section class="card"><h2>2. Update ausführen</h2><?php if(!$fresh):?><p>Erst möglich, wenn eine Sicherung aus den letzten zwei Stunden vorliegt.</p><?php else:?>
<form method="post"><?php gszFields('upgrade');?><input type="hidden" name="backup_sha256" value="<?=e($latest['sha256'])?>"><label class="check-label"><input type="checkbox" name="backup_kept" value="1" required> Ich habe die Sicherung heruntergeladen und aufbewahrt.</label><label>Dein Passwort zur Bestätigung<input name="owner_password" type="password" autocomplete="current-password" required></label><button class="primary">Update jetzt ausführen</button></form>
<p class="hint">Falls etwas schiefgeht: Anleitung „ROLLBACK.md“ im Paket. Die Sicherung kann in phpMyAdmin (STRATO-Kundenbereich) importiert werden.</p><?php endif?></section>
<?php elseif(gszRepairable380($inspection)):?>
<section class="card"><h2>Kleine Abweichung angleichen</h2><p>Bei deinem Hoster wurde eine neue Spalte mit einem älteren Zeichensatz angelegt. Das wird hier angeglichen; Inhalte bleiben unverändert.</p></section>
<section class="card"><h2>1. Sicherung erstellen</h2><form method="post"><?php gszFields('backup');?><button class="primary">Sicherung jetzt erstellen</button></form>
<?php foreach($backups as $b):?><p><a href="backup_download.php?file=<?=e(rawurlencode($b['file']))?>">Sicherung vom <?=e((new DateTimeImmutable($b['created_at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y, H:i'))?> Uhr herunterladen</a></p><?php endforeach?></section>
<section class="card"><h2>2. Angleichen</h2><?php if(!$fresh):?><p>Erst möglich, wenn eine Sicherung aus den letzten zwei Stunden vorliegt.</p><?php else:?><form method="post"><?php gszFields('repair');?><input type="hidden" name="backup_sha256" value="<?=e($latest['sha256'])?>"><label class="check-label"><input type="checkbox" name="backup_kept" value="1" required> Ich habe die Sicherung heruntergeladen und aufbewahrt.</label><label>Dein Passwort zur Bestätigung<input name="owner_password" type="password" autocomplete="current-password" required></label><button class="primary">Jetzt angleichen</button></form><?php endif?></section>
<?php else:?>
<section class="card"><h2>Update nicht möglich</h2><p><?=e(gszSetupSchemaMessage((string)$inspection['code']))?></p><p>Es wurde nichts verändert. Die bisherige Zentrale (alter Ordner) funktioniert mit dieser Datenbank unverändert weiter.</p></section>
<?php try{$diag=gszSetupSchemaDiagnosis($pdo,$inspection);}catch(Throwable $e){$diag=['fehler'=>'Diagnose nicht möglich'];}?><details class="card" open><summary>Technische Details (zum Weitergeben)</summary><p class="hint">Nur die Struktur der Datenbank: Tabellen- und Spaltennamen, keine Inhalte und keine Zugangsdaten. Text markieren, kopieren und weitergeben.</p><pre><?=e(json_encode($diag,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?></pre></details>
<?php endif;gszPageEnd();
